  const save=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch(error){}};save();
  const esc=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
