  let activeView=tabs.some(([id])=>id===location.hash.slice(1))?location.hash.slice(1):'overview';
  host.className='dnc-root';host.innerHTML=`<section class="dnc-hero"><div><div class="dnc-eyebrow">ROOT · Authoritative control plane</div><h2>DNS Infrastructure</h2><p>Govern authoritative zones, reusable templates, cluster replication, nameserver brands, DNSSEC signing and external providers from one operational center.</p></div><div class="dnc-hero-actions"><button class="wcp-action-btn" type="button" data-dnc-action="reconcile"><span class="material-symbols-rounded">sync</span>Reconcile cluster</button><button class="wcp-action-btn primary" type="button" data-dnc-action="add-zone"><span class="material-symbols-rounded">add</span>Add zone</button></div></section><div class="dnc-feedback" role="status" aria-live="polite"></div><section class="dnc-metrics" aria-label="DNS infrastructure summary"><article class="dnc-metric"><span>Authoritative zones</span><strong data-dnc-metric="zones"></strong><small>Account, system and reverse zones</small></article><article class="dnc-metric"><span>Cluster quorum</span><strong data-dnc-metric="nodes"></strong><small>Serial-aware multi-region replication</small></article><article class="dnc-metric"><span>DNSSEC coverage</span><strong>91%</strong><small>1,168 signed production zones</small></article><article class="dnc-metric"><span>Replication lag · p95</span><strong>214 ms</strong><small>Within the 500 ms platform SLO</small></article></section><section class="dnc-boundary" aria-label="Responsibility boundary"><div><span>ROOT owns</span><strong>Daemons, cluster, templates, signing, providers and hard floors</strong></div><span class="material-symbols-rounded">arrow_forward</span><div><span>RESELLER may</span><strong>Choose an allowed template, branded nameservers and narrower record policy</strong></div><span class="material-symbols-rounded">arrow_forward</span><div><span>USER owns</span><strong>Records inside assigned zones and effective record types only</strong></div></section><nav class="dnc-tabs" role="tablist" aria-label="DNS infrastructure views">${tabs.map(([id,icon,label])=>`<button class="dnc-tab${id===activeView?' active':''}" type="button" role="tab" aria-selected="${id===activeView}" data-dnc-tab="${id}"><span class="material-symbols-rounded">${icon}</span>${label}</button>`).join('')}</nav><main class="dnc-view" data-dnc-view tabindex="-1"></main>`;
