  const renderOverview=()=>`<section class="dnc-section">${sectionHead('Authoritative publication path','Every change is validated, versioned, signed where required, replicated and checked externally before success is reported.')}<div class="dnc-flow">${[['edit_note','Propose','Account or ROOT change'],['fact_check','Validate','Syntax, policy and ownership'],['difference','Review','Diff and approval rules'],['verified_user','Sign','DNSSEC when required'],['hub','Replicate','Quorum and serial ACK'],['travel_explore','Verify','Delegation and propagation']].map(([icon,title,copy])=>`<div class="dnc-flow-step"><span class="material-symbols-rounded">${icon}</span><strong>${title}</strong><small>${copy}</small></div>`).join('')}</div><div class="dnc-grid"><article class="dnc-card"><div class="dnc-card-head"><div class="dnc-card-icon"><span class="material-symbols-rounded">hub</span></div>${badge('Quorum 6 / 6','success')}</div><h4>Authoritative cluster</h4><p>Primary signing and multi-region secondaries use serial acknowledgements, drift repair and safe quorum gates.</p><div class="dnc-kv"><div><span>Service</span><strong>PowerDNS Authoritative</strong></div><div><span>Public recursion</span><strong>Denied</strong></div><div><span>Last full reconcile</span><strong>8 minutes ago</strong></div></div></article><article class="dnc-card"><div class="dnc-card-head"><div class="dnc-card-icon"><span class="material-symbols-rounded">verified_user</span></div>${badge('91% signed','processing')}</div><h4>DNSSEC lifecycle</h4><p>KSK and ZSK custody, pre-publication, rollover, DS delivery and validation are one auditable workflow.</p><div class="dnc-kv"><div><span>Algorithm floor</span><strong>ECDSAP256SHA256</strong></div><div><span>Next rollover</span><strong>2026-11-15</strong></div><div><span>DS automation</span><strong>1,142 registrars</strong></div></div></article><article class="dnc-card"><div class="dnc-card-head"><div class="dnc-card-icon"><span class="material-symbols-rounded">account_tree</span></div>${badge('Resolved policy','success')}</div><h4>Effective tenant policy</h4><p>The USER editor receives the intersection of ROOT record types, reseller restrictions, plan features and zone ownership.</p><div class="dnc-kv"><div><span>ROOT record types</span><strong>${state.recordTypes.filter(item=>item.enabled).map(item=>item.id).join(', ')}</strong></div><div><span>Reseller may widen</span><strong>Never</strong></div><div><span>Out-of-zone writes</span><strong>Denied</strong></div></div></article></div><div class="dnc-panel"><div class="dnc-panel-head"><div><strong>Operational attention</strong><small>Conditions that need review without mixing tenant DNS editing into ROOT infrastructure.</small></div><a class="wcp-action-btn" href="logs-diagnostics.html">Open diagnostics</a></div><div class="dnc-list"><div class="dnc-list-row"><span class="material-symbols-rounded">warning</span><div><strong>Two branded delegations do not match</strong><small>Agency nameserver glue and registrar delegation require reconciliation.</small></div>${badge('Review','warning')}</div><div class="dnc-list-row"><span class="material-symbols-rounded">key</span><div><strong>Twelve RSA zones await DNSSEC migration</strong><small>ECDSA-compatible registrars were detected and can enter the staged rollover.</small></div>${badge('Planned','processing')}</div><div class="dnc-list-row"><span class="material-symbols-rounded">public</span><div><strong>Singapore secondary exceeds regional target</strong><small>418 ms replication remains below the global SLO but above the 300 ms regional target.</small></div>${badge('Observed','warning')}</div></div></div></section>`;
  const renderZones=()=>`<section class="dnc-section">${sectionHead('Authoritative zone inventory','Ownership, current serial, signing and drift state stay visible before opening tenant records.','<button class="wcp-action-btn primary" type="button" data-dnc-action="add-zone"><span class="material-symbols-rounded">add</span>Add zone</button>')}<div class="dnc-panel"><div class="dnc-toolbar"><label class="dnc-search"><span class="material-symbols-rounded">search</span><input type="search" data-dnc-search placeholder="Search zone, account or owner" aria-label="Search DNS zones"></label><select data-dnc-filter aria-label="Filter zone state"><option value="">All states</option><option>In sync</option><option>Review</option><option>Restricted</option></select></div><div class="dnc-table-wrap"><table class="dnc-table"><thead><tr><th>Zone / owner</th><th>Account</th><th>Primary</th><th>Records</th><th>Serial</th><th>DNSSEC</th><th>Drift</th><th>State</th><th>Actions</th></tr></thead><tbody>${state.zones.map(zone=>`<tr data-dnc-zone="${esc(zone.id)}" data-search="${esc(`${zone.name} ${zone.account} ${zone.owner}`.toLowerCase())}" data-state="${esc(zone.state)}"><td><strong>${esc(zone.name)}</strong><small>${esc(zone.owner)}</small></td><td>${esc(zone.account)}</td><td>${esc(zone.node)}</td><td>${zone.records}</td><td><span class="dnc-code">${esc(zone.serial)}</span></td><td>${badge(zone.dnssec,tone(zone.dnssec))}</td><td>${esc(zone.drift)}</td><td>${badge(zone.state,tone(zone.state))}</td><td><div class="dnc-row-actions"><button class="wcp-action-btn" type="button" data-dnc-manage-zone="${esc(zone.id)}">Manage</button><button class="wcp-icon-btn" type="button" data-dnc-delete-zone="${esc(zone.id)}" aria-label="Delete ${esc(zone.name)}"><span class="material-symbols-rounded">delete</span></button></div></td></tr>`).join('')}</tbody></table><div class="dnc-empty" data-dnc-empty>No zone matches this filter.</div></div></div></section>`;
  const renderTemplates=()=>`<section class="dnc-section">${sectionHead('Versioned zone templates','Defaults are copied with provenance; later template changes produce a reviewable drift diff instead of overwriting customer records.','<button class="wcp-action-btn primary" type="button" data-dnc-action="add-template"><span class="material-symbols-rounded">add</span>Create template</button>')}<div class="dnc-grid">${state.templates.map(item=>`<article class="dnc-card" data-dnc-template="${esc(item.id)}"><div class="dnc-card-head"><div class="dnc-card-icon"><span class="material-symbols-rounded">description</span></div>${badge(item.state,tone(item.state))}</div><h4>${esc(item.name)} · ${esc(item.version)}</h4><p>${esc(item.includes)}</p><div class="dnc-kv"><div><span>Assignment</span><strong>${esc(item.scope)}</strong></div><div><span>Records</span><strong>${item.records}</strong></div><div><span>Adoption</span><strong>${esc(item.adoption)}</strong></div></div><footer><span class="dnc-badge">Immutable versions</span><button class="wcp-action-btn" type="button" data-dnc-inspect="template:${esc(item.id)}">Inspect</button></footer></article>`).join('')}</div></section>`;
  const renderCluster=()=>`<section class="dnc-section">${sectionHead('Authoritative cluster & replication','Roles, addresses, region, serial convergence and replication lag are managed as one topology.','<button class="wcp-action-btn primary" type="button" data-dnc-action="add-node"><span class="material-symbols-rounded">add</span>Add node</button>')}<div class="dnc-panel"><div class="dnc-table-wrap"><table class="dnc-table"><thead><tr><th>Node</th><th>Role</th><th>Region</th><th>Addresses</th><th>Zones</th><th>Lag</th><th>Serial</th><th>State</th><th>Action</th></tr></thead><tbody>${state.nodes.map(node=>`<tr data-dnc-node="${esc(node.id)}"><td><strong>${esc(node.name)}</strong></td><td>${esc(node.role)}</td><td>${esc(node.region)}</td><td><small>${esc(node.address)}</small></td><td>${node.zones.toLocaleString('en-US')}</td><td>${esc(node.lag)}</td><td>${esc(node.serial)}</td><td>${badge(node.state,tone(node.state))}</td><td><button class="wcp-action-btn" type="button" data-dnc-inspect="node:${esc(node.id)}">Inspect</button></td></tr>`).join('')}</tbody></table></div></div><div class="dnc-grid two"><article class="dnc-card"><h4>Replication safety</h4><p>Writes require primary validation and quorum acknowledgement. A stale node is removed from publication before repair.</p><div class="dnc-kv"><div><span>Write quorum</span><strong>4 of 6</strong></div><div><span>Maximum tolerated lag</span><strong>500 ms</strong></div><div><span>Automatic serial repair</span><strong>Enabled</strong></div></div></article><article class="dnc-card"><h4>Service probes</h4><p>UDP/TCP 53, DNSSEC validation, AXFR restrictions, recursion denial and response correctness run continuously.</p><div class="dnc-kv"><div><span>Probe interval</span><strong>30 seconds</strong></div><div><span>Anycast locations</span><strong>3 regions</strong></div><div><span>Errors · 24 h</span><strong>0 failed answers</strong></div></div></article></div></section>`;
  const renderNameservers=()=>`<section class="dnc-section">${sectionHead('Nameserver sets, glue & delegation','Configure the default platform nameservers, branded reseller sets, IP glue and registrar publication evidence.','<button class="wcp-action-btn" type="button" data-dnc-action="audit-delegation"><span class="material-symbols-rounded">travel_explore</span>Audit delegation</button><button class="wcp-action-btn primary" type="button" data-dnc-action="add-nameserver"><span class="material-symbols-rounded">add</span>Create nameserver set</button>')}<div class="dnc-grid two"><article class="dnc-card"><h4>Platform default</h4><p>${esc(state.nameservers.find(item=>item.isDefault)?.hosts||state.nameservers[0]?.hosts||'Not configured')}</p><div class="dnc-kv"><div><span>IPv4 glue</span><strong>${esc(state.nameservers.find(item=>item.isDefault)?.ipv4||'Not configured')}</strong></div><div><span>IPv6 glue</span><strong>${esc(state.nameservers.find(item=>item.isDefault)?.ipv6||'Not configured')}</strong></div><div><span>New zones</span><strong>Use this set unless plan/reseller overrides it</strong></div></div></article><article class="dnc-card"><h4>Publication contract</h4><p>Host objects and glue are checked at the registrar before a set can be assigned. Delegation drift opens an incident and never rewrites customer registrar data silently.</p><div class="dnc-kv"><div><span>Required addresses</span><strong>Two distinct authoritative endpoints</strong></div><div><span>Registrar evidence</span><strong>Receipt + external resolution</strong></div><div><span>Reseller boundary</span><strong>Published sets only</strong></div></div></article></div><div class="dnc-panel"><div class="dnc-table-wrap"><table class="dnc-table"><thead><tr><th>Set</th><th>Scope</th><th>Hostnames</th><th>Address glue</th><th>Registrar</th><th>Delegation</th><th>State</th><th>Actions</th></tr></thead><tbody>${state.nameservers.map(item=>`<tr data-dnc-nameserver="${esc(item.id)}"><td><strong>${esc(item.name)}</strong><small>${item.isDefault?'Platform default':esc(item.reseller==='No'?'ROOT managed':`Reseller: ${item.reseller}`)}</small></td><td>${esc(item.scope)}</td><td><small>${esc(item.hosts)}</small></td><td><small>IPv4: ${esc(item.ipv4||item.glue)}<br>IPv6: ${esc(item.ipv6||'Not configured')}</small></td><td>${esc(item.registrar||'Manual')}</td><td>${esc(item.delegation)}</td><td>${badge(item.state,tone(item.state))}</td><td><button class="wcp-action-btn" type="button" data-dnc-manage-nameserver="${esc(item.id)}">Configure</button></td></tr>`).join('')}</tbody></table></div></div><div class="dnc-form-note">Nameserver service, host/glue objects and authoritative publication are part of the WCP360 core. Registrar-specific APIs remain replaceable provider adapters; RESELLER can only select a ROOT-published set assigned to its envelope.</div></section>`;
  const renderDnssec=()=>`<section class="dnc-section">${sectionHead('DNSSEC keys, rollover & DS delivery','Key material stays in the vault/HSM; the panel exposes custody metadata, lifecycle state and registrar evidence only.','<button class="wcp-action-btn primary" type="button" data-dnc-action="rollover"><span class="material-symbols-rounded">sync_lock</span>Plan rollover</button>')}<div class="dnc-panel"><div class="dnc-table-wrap"><table class="dnc-table"><thead><tr><th>Key policy</th><th>Scope</th><th>Algorithm</th><th>Key tag</th><th>Rollover</th><th>DS publication</th><th>State</th></tr></thead><tbody>${state.dnssec.map(item=>`<tr data-dnc-dnssec="${esc(item.id)}"><td><strong>${esc(item.name)}</strong></td><td>${esc(item.scope)}</td><td>${esc(item.algorithm)}</td><td><span class="dnc-code">${esc(item.keyTag)}</span></td><td>${esc(item.rollover)}</td><td>${esc(item.ds)}</td><td>${badge(item.state,tone(item.state))}</td></tr>`).join('')}</tbody></table></div></div><div class="dnc-grid two"><article class="dnc-card"><h4>Rollover sequence</h4><p>Generate in HSM, pre-publish, verify propagation, activate, submit DS when needed, observe and retire safely.</p></article><article class="dnc-card"><h4>Failure containment</h4><p>Validation failures pause publication and retain the previous signing set. Emergency unsigned fallback requires two ROOT approvals.</p></article></div></section>`;
  const renderProviders=()=>`<section class="dnc-section">${sectionHead('Authoritative engines & external providers','Credentials are referenced from the vault, tested with least privilege and scoped to explicit zones.','<button class="wcp-action-btn primary" type="button" data-dnc-action="add-provider"><span class="material-symbols-rounded">add</span>Add provider</button>')}<div class="dnc-grid two">${state.providers.map(item=>`<article class="dnc-card" data-dnc-provider="${esc(item.id)}"><div class="dnc-card-head"><div class="dnc-card-icon"><span class="material-symbols-rounded">cloud_sync</span></div><label class="dnc-toggle"><input type="checkbox" data-dnc-provider-toggle="${esc(item.id)}" ${item.enabled?'checked':''} ${item.id==='powerdns'?'disabled':''} aria-label="Enable ${esc(item.name)}"><span>${item.enabled?'Enabled':'Disabled'}</span></label></div><h4>${esc(item.name)}</h4><p>${esc(item.kind)}</p><div class="dnc-kv"><div><span>Zone scope</span><strong>${esc(item.scope)}</strong></div><div><span>Credential</span><strong>${esc(item.credential)}</strong></div><div><span>Health</span><strong>${esc(item.health)}</strong></div><div><span>State</span><strong>${esc(item.state)}</strong></div></div><footer><button class="wcp-action-btn" type="button" data-dnc-test-provider="${esc(item.id)}">Test connection</button><button class="wcp-action-btn" type="button" data-dnc-inspect="provider:${esc(item.id)}">Inspect</button></footer></article>`).join('')}</div></section>`;
  const policyMeta={defaultTtl:['Default TTL','Applied to newly created records.'],minimumTtl:['Minimum TTL','Lower values are rejected by the effective editor.'],negativeTtl:['Negative cache TTL','SOA negative caching floor.'],dnssec:['DNSSEC floor','May be stricter per plan, never weaker downstream.'],caa:['CAA baseline','Prevents unintended certificate authorities.'],zoneTransfers:['Zone transfers','AXFR/IXFR source authorization.'],recursion:['Authoritative recursion','Must remain denied on public nodes.'],rateLimit:['Response rate limit','Per-source abuse protection.'],drift:['Template drift','How changed defaults reach existing zones.'],externalProviders:['External provider access','Account eligibility for remote DNS adapters.']};
  const renderPolicies=()=>`<section class="dnc-section">${sectionHead('Global DNS policy floor','RESELLER can narrow these values. USER receives only the effective record types and limits resolved for its zone.','<button class="wcp-action-btn primary" type="button" data-dnc-action="save-policies"><span class="material-symbols-rounded">publish</span>Publish policy</button>')}<div class="dnc-policy-grid">${Object.entries(state.policies).map(([key,value])=>`<label class="dnc-policy"><span><strong>${esc(policyMeta[key][0])}</strong><small>${esc(policyMeta[key][1])}</small></span><input name="${esc(key)}" value="${esc(value)}" data-dnc-policy></label>`).join('')}</div><div class="dnc-panel"><div class="dnc-panel-head"><div><strong>Record types visible downstream</strong><small>Disabled types disappear from USER create/edit workflows; existing records stay visible for safe remediation.</small></div></div><div class="dnc-list">${state.recordTypes.map(item=>`<div class="dnc-list-row" data-dnc-record-type="${esc(item.id)}"><span class="material-symbols-rounded">dns</span><div><strong>${esc(item.id)} records</strong><small>${item.enabled?'Available to eligible zones; reseller policy may still hide it.':'Creation disabled globally; existing values are read-only.'}</small></div><label class="dnc-toggle"><input type="checkbox" data-dnc-record-toggle="${esc(item.id)}" ${item.enabled?'checked':''}><span>${item.enabled?'Allowed':'Denied'}</span></label></div>`).join('')}</div></div></section>`;
  const renderHistory=()=>`<section class="dnc-section">${sectionHead('Immutable DNS history','Zone publication, template revisions, key operations, provider changes and reconciliation jobs correlate with audit evidence.','<a class="wcp-action-btn" href="audit-explorer.html"><span class="material-symbols-rounded">manage_search</span>Audit Explorer</a>')}<div class="dnc-panel"><div class="dnc-timeline">${state.events.map((event,index)=>`<div class="dnc-event" data-dnc-event="${index}"><time>${esc(event.time)}</time><i></i><div><strong>${esc(event.title)}</strong><small>${esc(event.detail)}</small></div>${badge(event.tone==='warning'?'Attention':event.tone==='processing'?'In progress':'Succeeded',event.tone)}</div>`).join('')}</div></div></section>`;
  const renderers={overview:renderOverview,zones:renderZones,templates:renderTemplates,cluster:renderCluster,nameservers:renderNameservers,dnssec:renderDnssec,providers:renderProviders,policies:renderPolicies,history:renderHistory};
  const render=()=>{updateMetrics();view.innerHTML=renderers[activeView]();bindView();bindNameserverView()};
  const filterZones=()=>{const term=(view.querySelector('[data-dnc-search]')?.value||'').toLowerCase(),status=view.querySelector('[data-dnc-filter]')?.value||'';let visible=0;view.querySelectorAll('[data-dnc-zone]').forEach(row=>{const show=(!term||row.dataset.search.includes(term))&&(!status||row.dataset.state===status);row.hidden=!show;if(show)visible++});const empty=view.querySelector('[data-dnc-empty]');if(empty)empty.style.display=visible?'none':'block'};
  const bindView=()=>{view.querySelector('[data-dnc-search]')?.addEventListener('input',filterZones);view.querySelector('[data-dnc-filter]')?.addEventListener('change',filterZones);view.querySelectorAll('[data-dnc-action]').forEach(button=>button.addEventListener('click',()=>handleAction(button.dataset.dncAction)));view.querySelectorAll('[data-dnc-manage-zone]').forEach(button=>button.addEventListener('click',()=>openInspect('zone',button.dataset.dncManageZone)));view.querySelectorAll('[data-dnc-delete-zone]').forEach(button=>button.addEventListener('click',()=>openDeleteZone(button.dataset.dncDeleteZone)));view.querySelectorAll('[data-dnc-inspect]').forEach(button=>button.addEventListener('click',()=>{const [kind,id]=button.dataset.dncInspect.split(':');openInspect(kind,id)}));view.querySelectorAll('[data-dnc-provider-toggle]').forEach(toggle=>toggle.addEventListener('change',()=>toggleProvider(toggle)));view.querySelectorAll('[data-dnc-test-provider]').forEach(button=>button.addEventListener('click',()=>{const item=state.providers.find(provider=>provider.id===button.dataset.dncTestProvider);showFeedback(`${item.name} credential, permissions and API round-trip were queued for testing.`);operation(`Test DNS provider ${item.name}`,'dns-provider')}));view.querySelectorAll('[data-dnc-record-toggle]').forEach(toggle=>toggle.addEventListener('change',()=>toggleRecordType(toggle)))};
  const bindNameserverView=()=>{view.querySelectorAll('[data-dnc-manage-nameserver]').forEach(button=>button.addEventListener('click',()=>openNameserverForm(button.dataset.dncManageNameserver)));view.querySelector('[data-dnc-action="add-nameserver"]')?.addEventListener('click',()=>openNameserverForm(''));view.querySelector('[data-dnc-action="audit-delegation"]')?.addEventListener('click',()=>{state.events.unshift({time:'Just now',title:'Nameserver delegation audit started',detail:'WCP360 System · host glue, registrar delegation and authoritative answers',tone:'processing'});save();showFeedback('Nameserver glue and delegation audit was added to the Job Center.');operation('Audit nameserver glue and delegation','dns-nameserver')})};
  const switchView=id=>{if(!renderers[id])return;activeView=id;host.querySelectorAll('[data-dnc-tab]').forEach(item=>{const active=item.dataset.dncTab===id;item.classList.toggle('active',active);item.setAttribute('aria-selected',String(active))});history.replaceState(null,'',`#${id}`);render();view.focus({preventScroll:true})};
  host.querySelectorAll('[data-dnc-tab]').forEach(tab=>tab.addEventListener('click',()=>switchView(tab.dataset.dncTab)));host.querySelectorAll('[data-dnc-open-view]').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.dncOpenView)));window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(renderers[id]&&id!==activeView)switchView(id)});
  const wrapper=document.createElement('div');wrapper.innerHTML=`<button class="dnc-drawer-backdrop" type="button" data-dnc-close aria-label="Close DNS workflow"></button><aside class="dnc-drawer" id="dnsCenterDrawer" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="dnsCenterDrawerTitle"><div class="dnc-drawer-head"><div><strong id="dnsCenterDrawerTitle">DNS workflow</strong><small data-dnc-drawer-sub>Privileged ROOT operation</small></div><button class="wcp-icon-btn" type="button" data-dnc-close aria-label="Close"><span class="material-symbols-rounded">close</span></button></div><div class="dnc-drawer-body" data-dnc-drawer-body></div></aside>`;document.body.append(...wrapper.children);
  const drawer=document.querySelector('#dnsCenterDrawer'),backdrop=document.querySelector('.dnc-drawer-backdrop'),drawerBody=drawer.querySelector('[data-dnc-drawer-body]');let returnFocus;
  const openDrawer=(title,subtitle,content)=>{returnFocus=document.activeElement;drawer.querySelector('#dnsCenterDrawerTitle').textContent=title;drawer.querySelector('[data-dnc-drawer-sub]').textContent=subtitle;drawerBody.innerHTML=content;drawer.classList.add('open');backdrop.classList.add('open');drawer.setAttribute('aria-hidden','false');setTimeout(()=>drawerBody.querySelector('input,select,button')?.focus(),20)};
  const closeDrawer=()=>{drawer.classList.remove('open');backdrop.classList.remove('open');drawer.setAttribute('aria-hidden','true');returnFocus?.focus?.()};document.querySelectorAll('[data-dnc-close]').forEach(button=>button.addEventListener('click',closeDrawer));
  const formActions='<div class="dnc-form-actions"><button class="wcp-action-btn" type="button" data-dnc-close-form>Cancel</button><button class="wcp-action-btn primary" type="submit">Review &amp; create job</button></div>';
