  const openAddZone=()=>{openDrawer('Add authoritative zone','Ownership, template and signing policy',`<form class="dnc-form" data-dnc-form="add-zone"><label class="dnc-field"><span>Zone name</span><input name="name" value="new.example.com" required pattern="[A-Za-z0-9.-]+"></label><div class="dnc-form-grid"><label class="dnc-field"><span>Hosting account</span><input name="account" value="example.com" required></label><label class="dnc-field"><span>Owner</span><input name="owner" value="Yann Gerard" required></label><label class="dnc-field"><span>Zone template</span><select name="template">${state.templates.filter(item=>item.state==='Published').map(item=>`<option>${esc(item.name)} ${esc(item.version)}</option>`).join('')}</select></label><label class="dnc-field"><span>DNSSEC</span><select name="dnssec"><option>Sign immediately</option><option>Stage unsigned</option></select></label><label class="dnc-field"><span>Nameserver set</span><select name="nameservers">${state.nameservers.filter(item=>item.state==='Active').map(item=>`<option>${esc(item.name)}</option>`).join('')}</select></label><label class="dnc-field"><span>Provider</span><select name="provider">${state.providers.filter(item=>item.enabled).map(item=>`<option>${esc(item.name)}</option>`).join('')}</select></label></div><div class="dnc-form-note">Preflight verifies zone uniqueness, account ownership, delegation conflicts, provider access, template syntax, DNSSEC compatibility and rollback readiness.</div>${formActions}</form>`);bindForm()};
